using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.ComponentModel;using System.Runtime.Serialization;
namespace CircuitoStudio {
[DataContract]public enum ReturnRole{[EnumMember] Neutral,[EnumMember] PE,[EnumMember] PEN}
[DataContract]public enum NeutralSizingMode{[EnumMember] FullPhase,[EnumMember] Reduced}
[DataContract]public enum ProtectiveSizingMethod{[EnumMember] RelatedPhase,[EnumMember] Adiabatic}
[DataContract]public sealed class ReturnConductorRating {
[DataMember]public ReturnRole Role{get;set;}[DataMember]public ConductorMaterial Material{get;set;}[DataMember]public double SectionMm2{get;set;}[DataMember]public double CorrectedIzA{get;set;}[DataMember]public double? ResistanceOhmKm{get;set;}[DataMember]public double? ReactanceOhmKm{get;set;}[DataMember]public string Reference{get;set;}[DataMember]public string Source{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember]public string Conditions{get;set;}
public ReturnConductorRating(){Reference=Source=DataVersion=Conditions="";}public ReturnConductorRating Copy(){return (ReturnConductorRating)MemberwiseClone();}
public void Validate(){if(!Enum.IsDefined(typeof(ReturnRole),Role)||!Enum.IsDefined(typeof(ConductorMaterial),Material))throw new InvalidDataException("Papel/material do condutor inválidos.");Project.Range(SectionMm2,.001,1e6,"seção retorno");Project.Range(CorrectedIzA,0,1e12,"Iz retorno");foreach(var v in new[]{ResistanceOhmKm,ReactanceOhmKm})if(v.HasValue)Project.Range(v.Value,0,1e12,"R/X retorno");foreach(var s in new[]{Reference,Source,DataVersion,Conditions})ReturnSizing.Text(s,true);}
}
[DataContract]public sealed class ReturnSizingRequirements {
[DataMember,DisplayName("Neutro: mesma seção ou redução")]public NeutralSizingMode NeutralMode{get;set;}[DataMember,DisplayName("Método do PE/PEN")]public ProtectiveSizingMethod ProtectiveMethod{get;set;}[DataMember,DisplayName("Harmônicas e desequilíbrio avaliados")]public bool? HarmonicsAssessed{get;set;}[DataMember,DisplayName("Corrente RMS de projeto N/PEN (A)")]public double? NeutralDesignRmsA{get;set;}[DataMember,DisplayName("Fonte da corrente RMS")]public string NeutralCurrentSource{get;set;}[DataMember,DisplayName("Condições exatas da Iz de N/PEN")]public string NeutralAmpacityConditions{get;set;}[DataMember,DisplayName("In da proteção aplicável a N (A)")]public double? NeutralProtectiveRatedA{get;set;}[DataMember,DisplayName("I2 da proteção aplicável a N (A)")]public double? NeutralProtectiveI2A{get;set;}[DataMember,DisplayName("Proteção de sobrecorrente cobre N")]public bool? NeutralProtectionApplies{get;set;}[DataMember,DisplayName("Documento da proteção de N")]public string NeutralProtectionReference{get;set;}[DataMember,DisplayName("Assinatura dos dispositivos")]public string ProtectionConfiguration{get;set;}[DataMember,DisplayName("PEN sem interrupção/seccionamento")]public bool? PENNotSwitched{get;set;}[DataMember,DisplayName("Corrente de fuga no PE (mA)")]public double? ProtectiveLeakageMilliA{get;set;}[DataMember,DisplayName("Fonte da corrente de fuga")]public string LeakageReference{get;set;}[DataMember,DisplayName("Instalação fixa (PEN)")]public bool? FixedInstallation{get;set;}[DataMember,DisplayName("PE separado do cabo de fase")]public bool? SeparateFromPhase{get;set;}[DataMember,DisplayName("PE com proteção mecânica")]public bool? MechanicallyProtected{get;set;}[DataMember,DisplayName("Energia de falta coberta (A²s)")]public double? LetThroughA2s{get;set;}[DataMember,DisplayName("Tempo total dessa falta (s)")]public double? ClearingSeconds{get;set;}[DataMember,DisplayName("k do PE/PEN declarado")]public double? ProtectiveK{get;set;}[DataMember,DisplayName("k do neutro declarado")]public double? NeutralK{get;set;}[DataMember,DisplayName("Fonte de I²t/tempo/k e condições")]public string ThermalReference{get;set;}[DataMember,DisplayName("Regra e fonte utilizadas")]public string RuleReference{get;set;}[DataMember,DisplayName("Edição/revisão escolhida")]public string RuleEdition{get;set;}[DataMember,DisplayName("Hipóteses e alcance da regra")]public string RuleConditions{get;set;}
public ReturnSizingRequirements(){NeutralCurrentSource=NeutralAmpacityConditions=NeutralProtectionReference=ProtectionConfiguration=ThermalReference=RuleReference=RuleEdition=RuleConditions=LeakageReference="";}
public ReturnSizingRequirements Copy(){return (ReturnSizingRequirements)MemberwiseClone();}
public void Validate(){if(!Enum.IsDefined(typeof(NeutralSizingMode),NeutralMode)||!Enum.IsDefined(typeof(ProtectiveSizingMethod),ProtectiveMethod))throw new InvalidDataException("Método de dimensionamento inválido.");foreach(var x in new[]{ProtectiveLeakageMilliA,NeutralDesignRmsA,NeutralProtectiveRatedA,NeutralProtectiveI2A,LetThroughA2s,ClearingSeconds,ProtectiveK,NeutralK})if(x.HasValue)Project.Range(x.Value,0,1e15,"dado de retorno");foreach(var s in new[]{LeakageReference,NeutralCurrentSource,NeutralAmpacityConditions,NeutralProtectionReference,ProtectionConfiguration,ThermalReference,RuleReference,RuleEdition,RuleConditions})ReturnSizing.Text(s,false);if(ProtectionConfiguration!=""&&(ProtectionConfiguration.Length!=64||ProtectionConfiguration.Any(x=>!Uri.IsHexDigit(x))))throw new InvalidDataException("Assinatura da proteção inválida.");}
}
[DataContract]public sealed class ReturnSizingBinding {
[DataMember]public string Engine{get;set;}[DataMember]public ReturnSizingRequirements Requirements{get;set;}[DataMember]public ReturnConductorRating Neutral{get;set;}[DataMember]public ReturnConductorRating Protective{get;set;}
public void Validate(){if(Engine!=ReturnSizing.EngineId||Requirements==null)throw new InvalidDataException("Revisão de dimensionamento de retornos desconhecida.");Requirements.Validate();if(Neutral==null&&Protective==null)throw new InvalidDataException("Selecione pelo menos um condutor.");if(Neutral!=null){Neutral.Validate();if(Neutral.Role!=ReturnRole.Neutral)throw new InvalidDataException("Papel inválido no neutro.");}if(Protective!=null){Protective.Validate();if(Protective.Role==ReturnRole.Neutral)throw new InvalidDataException("Papel inválido no protetor.");}if(Neutral!=null&&Protective!=null&&Protective.Role==ReturnRole.PEN)throw new InvalidDataException("PEN não pode ter N separado selecionado.");}
}
public sealed partial class Circuit{[DataMember(Order=112),Browsable(false)]public ReturnSizingBinding ReturnSizing{get;set;}}
public sealed class ReturnSizingEvaluation{public ReturnConductorRating Rating;public double MinimumSection;public string Status,Detail;}
public static class ReturnSizing {
public static string ProtectionContext(Circuit c){return Coordination.Configuration(c);}
public const string EngineId="cs-retornos-dimensionamento-v1";public const string Header="Role;Material;SectionMm2;CorrectedIzA;ResistanceOhmKm;ReactanceOhmKm;Reference;Source;DataVersion;Conditions";
internal static void Text(string s,bool required){if(s==null||s.Length>2000||s.IndexOf('\0')>=0||(required&&String.IsNullOrWhiteSpace(s)))throw new InvalidDataException("Referência de retorno ausente/inválida.");}
static void Rule(StringBuilder text,string name,bool? value,ref bool fail,ref bool pending){if(!value.HasValue)pending=true;else if(!value.Value)fail=true;text.AppendLine((value.HasValue?(value.Value?"Atende: ":"Não atende: "):"Pendente: ")+name);}
static bool? Known(bool? value){return value;}
public static ReturnSizingEvaluation Evaluate(Project p,Circuit c,ReturnSizingRequirements requirements,ReturnConductorRating rating){p.Validate();requirements.Validate();rating.Validate();if(!p.Boards.Any(b=>b.Circuits.Contains(c)))throw new InvalidDataException("Circuito fora do projeto.");bool fail=false,pending=false;var text=new StringBuilder();var w=c.Conductors;Rule(text,"Escopo CA de baixa tensão até1000V entre fases",p.Boards.First(b=>b.Circuits.Contains(c)).Voltage<=1000,ref fail,ref pending);bool neutral=rating.Role!=ReturnRole.PE,protective=rating.Role!=ReturnRole.Neutral;Rule(text,"Condutor presente no circuito tipado",w==null?(bool?)null:rating.Role==ReturnRole.PEN?w.HasPEN:rating.Role==ReturnRole.PE?w.HasPE:w.HasNeutral,ref fail,ref pending);Rule(text,"Mesma matéria do condutor de fase (escopo desta revisão)",rating.Material==c.Cable.Material,ref fail,ref pending);Rule(text,"Regra/referência, edição e hipóteses explicitadas",String.IsNullOrWhiteSpace(requirements.RuleReference)||String.IsNullOrWhiteSpace(requirements.RuleEdition)||String.IsNullOrWhiteSpace(requirements.RuleConditions)?(bool?)null:true,ref fail,ref pending);Rule(text,"Seção de fase conhecida e sem paralelos não modelados",c.CableMm2>0?(bool?)(c.Cable.Parallel==1):null,ref fail,ref pending);double minimum=0;bool copper=rating.Material==ConductorMaterial.Copper;bool context=requirements.ProtectionConfiguration!=""&&String.Equals(requirements.ProtectionConfiguration,ProtectionContext(c),StringComparison.OrdinalIgnoreCase);
if(neutral){double threshold=copper?16:25;double minNeutral=c.CableMm2;if(requirements.NeutralMode==NeutralSizingMode.Reduced){Rule(text,"Redução somente trifásica acima de "+threshold+" mm²",c.CableMm2>threshold&&c.Phases==PhaseMode.Trifasico,ref fail,ref pending);minNeutral=threshold;Rule(text,"Energia/tempo/k do neutro com proteção exata",EnergyKnown(requirements,requirements.NeutralK,context),ref fail,ref pending);if(EnergyKnown(requirements,requirements.NeutralK,context)==true)minNeutral=Math.Max(minNeutral,Math.Sqrt(requirements.LetThroughA2s.Value)/requirements.NeutralK.Value);}minimum=Math.Max(minimum,minNeutral);Rule(text,"Harmônicas, desequilíbrio e corrente RMS do neutro avaliados",Known(requirements.HarmonicsAssessed),ref fail,ref pending);Rule(text,"Corrente RMS do neutro documentada",requirements.NeutralDesignRmsA.HasValue&&!String.IsNullOrWhiteSpace(requirements.NeutralCurrentSource)?(bool?)true:null,ref fail,ref pending);Rule(text,"Iz corrigida nas mesmas condições declaradas",rating.CorrectedIzA>0&&!String.IsNullOrWhiteSpace(requirements.NeutralAmpacityConditions)?(bool?)(requirements.NeutralAmpacityConditions==rating.Conditions):null,ref fail,ref pending);Rule(text,"IN,RMS ≤ IzN",requirements.NeutralDesignRmsA.HasValue&&rating.CorrectedIzA>0?(bool?)(requirements.NeutralDesignRmsA.Value<=rating.CorrectedIzA):null,ref fail,ref pending);Rule(text,"Proteção de sobrecorrente aplicável ao N/PEN e associação exata",requirements.NeutralProtectionApplies.HasValue?(bool?)(requirements.NeutralProtectionApplies.Value&&context&&!String.IsNullOrWhiteSpace(requirements.NeutralProtectionReference)):null,ref fail,ref pending);Rule(text,"IN,RMS ≤ In,N ≤ IzN e I2,N ≤1,45IzN",requirements.NeutralDesignRmsA.HasValue&&requirements.NeutralProtectiveRatedA.HasValue&&requirements.NeutralProtectiveI2A.HasValue&&requirements.NeutralProtectiveRatedA>0&&requirements.NeutralProtectiveI2A>0&&rating.CorrectedIzA>0?(bool?)(requirements.NeutralDesignRmsA<=requirements.NeutralProtectiveRatedA&&requirements.NeutralProtectiveRatedA<=rating.CorrectedIzA&&requirements.NeutralProtectiveI2A<=1.45*rating.CorrectedIzA):null,ref fail,ref pending);}
if(protective){Rule(text,"Corrente de fuga no PE documentada",requirements.ProtectiveLeakageMilliA.HasValue&&!String.IsNullOrWhiteSpace(requirements.LeakageReference)?(bool?)true:null,ref fail,ref pending);if(requirements.ProtectiveLeakageMilliA>10)minimum=Math.Max(minimum,copper?10:16);if(requirements.ProtectiveMethod==ProtectiveSizingMethod.RelatedPhase)minimum=Math.Max(minimum,c.CableMm2<=16?c.CableMm2:c.CableMm2<=35?16:c.CableMm2/2);else{Rule(text,"I²t/tempo/k de PE/PEN com proteção exata",EnergyKnown(requirements,requirements.ProtectiveK,context),ref fail,ref pending);if(EnergyKnown(requirements,requirements.ProtectiveK,context)==true)minimum=Math.Max(minimum,Math.Sqrt(requirements.LetThroughA2s.Value)/requirements.ProtectiveK.Value);}if(rating.Role==ReturnRole.PE){Rule(text,"Disposição do PE declarada",requirements.SeparateFromPhase.HasValue?(bool?)true:null,ref fail,ref pending);if(requirements.SeparateFromPhase==true){Rule(text,"Proteção mecânica declarada",requirements.MechanicallyProtected.HasValue?(bool?)true:null,ref fail,ref pending);if(requirements.MechanicallyProtected.HasValue)minimum=Math.Max(minimum,copper?(requirements.MechanicallyProtected.Value?2.5:4):16);}}else{minimum=Math.Max(minimum,copper?10:16);Rule(text,"PEN somente instalação fixa",requirements.FixedInstallation,ref fail,ref pending);Rule(text,"PEN nunca interrompido/seccionado",requirements.PENNotSwitched,ref fail,ref pending);}}
Rule(text,"Seção "+rating.SectionMm2+" ≥ mínima calculada "+minimum+" mm²",c.CableMm2>0?(bool?)(rating.SectionMm2>=minimum):null,ref fail,ref pending);if(!Grounding.Complete(p,c)){pending=true;text.AppendLine("Pendente: cadastro tipado de aterramento/condutores incompleto.");}if(new[]{rating.Reference,rating.Source,rating.DataVersion,rating.Conditions,requirements.RuleReference,requirements.RuleEdition,requirements.RuleConditions,requirements.NeutralCurrentSource,requirements.NeutralProtectionReference,requirements.ThermalReference}.Any(s=>s.StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase))){pending=true;text.AppendLine("Pendente: modelo não preenchido.");}text.AppendLine("Dados de cálculo: fase="+c.CableMm2+" mm²; Iz retorno corrigida="+rating.CorrectedIzA+" A; R/X="+(rating.ResistanceOhmKm.HasValue?rating.ResistanceOhmKm+"":"desconhecida")+" / "+(rating.ReactanceOhmKm.HasValue?rating.ReactanceOhmKm+"":"desconhecida")+" Ω/km. Modo N="+requirements.NeutralMode+"; IN,RMS="+requirements.NeutralDesignRmsA+" A; fonte RMS="+requirements.NeutralCurrentSource+"; condições IzN="+requirements.NeutralAmpacityConditions+"; In,N/I2,N="+requirements.NeutralProtectiveRatedA+" / "+requirements.NeutralProtectiveI2A+" A; documento="+requirements.NeutralProtectionReference+". Método PE/PEN="+requirements.ProtectiveMethod+"; energia="+requirements.LetThroughA2s+" A²s; tempo total="+requirements.ClearingSeconds+" s; kPE/kN="+requirements.ProtectiveK+" / "+requirements.NeutralK+"; fonte térmica="+requirements.ThermalReference+"; fuga PE="+requirements.ProtectiveLeakageMilliA+" mA; fonte="+requirements.LeakageReference+"; assinatura salva="+requirements.ProtectionConfiguration+". Hipóteses de cobertura declaradas não autenticam fonte/certificação.");text.Insert(0,EngineId+"; "+rating.Role+" "+rating.SectionMm2+" mm² "+rating.Material+"; fonte "+rating.Source+"; versão "+rating.DataVersion+"; referência "+rating.Reference+"; condições "+rating.Conditions+". Regra "+requirements.RuleReference+"; edição "+requirements.RuleEdition+"; hipóteses "+requirements.RuleConditions+".\r\n");text.AppendLine("Menor seção apenas entre candidatos fornecidos, mesma matéria e um condutor por função. Não comprova laço/tempo/contato, continuidade física ou conformidade normativa integral. Corrente fundamental balanceada não prova neutro sem harmônicas. R/X desconhecidos não são substituídos por zero.");return new ReturnSizingEvaluation{Rating=rating,MinimumSection=minimum,Status=fail?"Não atende":pending?"Dados incompletos":"Atende critérios locais declarados",Detail=text.ToString()};}
static bool? EnergyKnown(ReturnSizingRequirements r,double? k,bool context){if(!r.LetThroughA2s.HasValue||!r.ClearingSeconds.HasValue||!k.HasValue||String.IsNullOrWhiteSpace(r.ThermalReference)||r.ProtectionConfiguration=="")return null;return r.LetThroughA2s>0&&r.ClearingSeconds>0&&r.ClearingSeconds<=5&&k>0&&context;}
public static ReturnSizingEvaluation Recommend(Project p,Circuit c,ReturnSizingRequirements requirements,IEnumerable<ReturnConductorRating> candidates,ReturnRole role){var rows=candidates.ToList();foreach(var row in rows)row.Validate();foreach(var row in rows.Where(x=>x.Role==role).OrderBy(x=>x.SectionMm2).ThenBy(x=>x.Reference,StringComparer.Ordinal)){var result=Evaluate(p,c,requirements,row);if(result.Status=="Atende critérios locais declarados")return result;}return null;}
public static void Apply(Project p,Circuit c,ReturnSizingBinding selection){selection.Validate();foreach(var row in new[]{selection.Neutral,selection.Protective}.Where(x=>x!=null))if(Evaluate(p,c,selection.Requirements,row).Status=="Não atende")throw new InvalidDataException("Seleção incompatível; nenhuma alteração.");var old=c.ReturnSizing;c.ReturnSizing=new ReturnSizingBinding{Engine=EngineId,Requirements=selection.Requirements.Copy(),Neutral=selection.Neutral==null?null:selection.Neutral.Copy(),Protective=selection.Protective==null?null:selection.Protective.Copy()};try{p.Validate();}catch{c.ReturnSizing=old;throw;}}
static string Key(ReturnConductorRating r){return r.Role+"\0"+r.Material+"\0"+r.Reference.Trim()+"\0"+r.SectionMm2.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+"\0"+r.Conditions.Trim();}
public static List<ReturnConductorRating> Import(string file){return ComponentCsv.Import<ReturnConductorRating>(file,Header,r=>r.Validate(),Key);}public static void Export(IEnumerable<ReturnConductorRating> rows,string file){ComponentCsv.Export(rows,file,Header,r=>r.Validate(),Key);}
}
